import sys
from bisect import bisect_left

def solve():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())

    intervals = []
    for _ in range(M):
        s, t = map(int, input().split())
        if s > t:
            s, t = t, s
        intervals.append((s, t))

    B = 1
    while B <= N:
        B <<= 1

    coords = [None] * (2 * B)

    # Build coordinate lists for the outer segment tree.
    for l, r in intervals:
        p = l + B
        while p:
            a = coords[p]
            if a is None:
                coords[p] = [r]
            else:
                a.append(r)
            p >>= 1

    trees = [None] * (2 * B)

    for i in range(1, 2 * B):
        a = coords[i]
        if a is not None:
            a.sort()
            unique = []
            prev = -1
            for x in a:
                if x != prev:
                    unique.append(x)
                    prev = x
            coords[i] = unique
            trees[i] = [0] * (2 * len(unique))

    def rectangle_max(xl, xr, yl, yr):
        """Maximum insertion index among points:
           xl <= x < xr and yl <= y < yr.
        """
        if xl >= xr or yl >= yr:
            return 0

        xl += B
        xr += B
        ans = 0

        while xl < xr:
            if xl & 1:
                ys = coords[xl]
                if ys is not None:
                    left = bisect_left(ys, yl)
                    right = bisect_left(ys, yr)
                    if left < right:
                        seg = trees[xl]
                        left += len(ys)
                        right += len(ys)
                        while left < right:
                            if left & 1:
                                v = seg[left]
                                if v > ans:
                                    ans = v
                                left += 1
                            if right & 1:
                                right -= 1
                                v = seg[right]
                                if v > ans:
                                    ans = v
                            left >>= 1
                            right >>= 1
                xl += 1

            if xr & 1:
                xr -= 1
                ys = coords[xr]
                if ys is not None:
                    left = bisect_left(ys, yl)
                    right = bisect_left(ys, yr)
                    if left < right:
                        seg = trees[xr]
                        left += len(ys)
                        right += len(ys)
                        while left < right:
                            if left & 1:
                                v = seg[left]
                                if v > ans:
                                    ans = v
                                left += 1
                            if right & 1:
                                right -= 1
                                v = seg[right]
                                if v > ans:
                                    ans = v
                            left >>= 1
                            right >>= 1

            xl >>= 1
            xr >>= 1

        return ans

    # For each endpoint, keep the latest interval and latest different partner.
    by_left = {}
    by_right = {}

    bad_prefix = [0] * (M + 1)
    current_bad = 0

    for idx, (l, r) in enumerate(intervals, 1):
        bad = 0

        # Proper crossing:
        # old_l < l < old_r < r
        v = rectangle_max(1, l, l + 1, r)
        if v > bad:
            bad = v

        # Proper crossing:
        # l < old_l < r < old_r
        v = rectangle_max(l + 1, r, r + 1, N + 1)
        if v > bad:
            bad = v

        # Same left endpoint but different right endpoint.
        info = by_left.get(l)
        if info is not None:
            p1, q1, p2, q2 = info
            if q1 != r:
                if p1 > bad:
                    bad = p1
            elif p2 > bad:
                bad = p2

        # Same right endpoint but different left endpoint.
        info = by_right.get(r)
        if info is not None:
            p1, q1, p2, q2 = info
            if q1 != l:
                if p1 > bad:
                    bad = p1
            elif p2 > bad:
                bad = p2

        if bad > current_bad:
            current_bad = bad
        bad_prefix[idx] = current_bad

        # Insert into the 2D range tree.
        p = l + B
        while p:
            ys = coords[p]
            pos = bisect_left(ys, r) + len(ys)
            seg = trees[p]
            seg[pos] = idx
            pos >>= 1
            while pos:
                seg[pos] = idx
                pos >>= 1
            p >>= 1

        # Update same-left tracking.
        info = by_left.get(l)
        if info is None:
            by_left[l] = (idx, r, 0, -1)
        else:
            p1, q1, p2, q2 = info
            if q1 == r:
                by_left[l] = (idx, r, p2, q2)
            else:
                by_left[l] = (idx, r, p1, q1)

        # Update same-right tracking.
        info = by_right.get(r)
        if info is None:
            by_right[r] = (idx, l, 0, -1)
        else:
            p1, q1, p2, q2 = info
            if q1 == l:
                by_right[r] = (idx, l, p2, q2)
            else:
                by_right[r] = (idx, l, p1, q1)

    out = []
    for _ in range(Q):
        L, R = map(int, input().split())
        if bad_prefix[R] < L:
            out.append("Yes")
        else:
            out.append("No")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        total = sum(nums)
        if k < -total or k > total:
            return -1

        offset = total
        target_bit = 1 << (k + offset)
        mask = (1 << (2 * total + 1)) - 1

        # dp[product] = [bitset for even-length subsequences,
        #                bitset for odd-length subsequences]
        # Bit position (sum + offset) indicates that alternating sum is possible.
        dp = {}

        for x in nums:
            # Snapshot is necessary because current element may not be reused.
            old_states = [(p, state[0], state[1]) for p, state in dp.items()]

            # Start a new subsequence with this single element.
            if x <= limit:
                state = dp.setdefault(x, [0, 0])
                state[1] |= 1 << (x + offset)

            for product, even_bits, odd_bits in old_states:
                new_product = product * x
                if new_product > limit:
                    continue

                state = dp.setdefault(new_product, [0, 0])

                # Appending to an even-length subsequence adds x.
                if even_bits:
                    state[1] |= (even_bits << x) & mask

                # Appending to an odd-length subsequence subtracts x.
                if odd_bits:
                    state[0] |= odd_bits >> x

        for product in sorted(dp.keys(), reverse=True):
            even_bits, odd_bits = dp[product]
            if (even_bits & target_bit) or (odd_bits & target_bit):
                return product

        return -1

