import sys

def solve():
    input = sys.stdin.readline
    T = int(input())
    out = []
    SHIFT = 500_000_000

    def add_piece(ch, r, c):
        out.append(f"{ch} {r + SHIFT} {c + SHIFT}")

    for _ in range(T):
        R, B = map(int, input().split())

        if R % 2 == 1:
            out.append("No")
            continue

        out.append("Yes")

        # Only blue pieces
        if R == 0:
            # B must be even because R+B >= 2 and R is even;
            # odd B is impossible, but it was not rejected above.
            if B % 2 == 1:
                out[-1] = "No"
                continue

            m = B // 2
            # In transformed coordinates:
            # r = x + y, c = x - y
            xy = [(0, 0), (1, 0)]
            h = m - 1
            for y in range(1, h + 1):
                xy.append((1, y))
            xy.append((0, h))
            for y in range(h - 1, -1, -1):
                xy.append((0, y))

            for x, y in xy[:-1]:
                add_piece("B", x + y, x - y)
            continue

        # Only red pieces
        if B == 0:
            if R == 2:
                add_piece("R", 0, 0)
                add_piece("R", 0, 1)
            else:
                k = R // 2
                w = k - 1
                path = [(0, 0)]
                for c in range(1, w + 1):
                    path.append((0, c))
                path.append((1, w))
                for c in range(w - 1, -1, -1):
                    path.append((1, c))

                for r, c in path:
                    add_piece("R", r, c)
            continue

        k = R // 2

        # Odd number of blue pieces:
        # red path from (0,0) to (1,1), then blue path back.
        if B % 2 == 1:
            m = B // 2

            red_path = [(0, 0)]
            for c in range(1, k + 1):
                red_path.append((0, c))
            red_path.append((1, k))
            for c in range(k - 1, 0, -1):
                red_path.append((1, c))

            for r, c in red_path[:-1]:
                add_piece("R", r, c)

            # Blue path in transformed coordinates:
            # starts at (1,0), ends at (0,0)
            xy = [(1, 0)]
            for y in range(1, m + 1):
                xy.append((1, y))
            xy.append((0, m))
            for y in range(m - 1, -1, -1):
                xy.append((0, y))

            for x, y in xy[:-1]:
                add_piece("B", x + y, x - y)

        # Positive even number of blue pieces:
        # red path from (0,0) to (0,2), then blue path back.
        else:
            m = B // 2

            red_path = [(0, 0)]
            for r in range(1, k):
                red_path.append((r, 0))
            red_path.append((k - 1, 1))
            red_path.append((k - 1, 2))
            for r in range(k - 2, -1, -1):
                red_path.append((r, 2))

            for r, c in red_path[:-1]:
                add_piece("R", r, c)

            # Starts at transformed coordinate (1,-1), ends at (0,0)
            xy = [(1, -1)]
            for j in range(2, m + 1):
                xy.append((1, -j))
            xy.append((0, -m))
            for y in range(-m + 1, 1):
                xy.append((0, y))

            for x, y in xy[:-1]:
                add_piece("B", x + y, x - y)

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

import sys

def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    t = next(it)
    out = []

    for _ in range(t):
        n = next(it)
        a = [next(it) for _ in range(n)]

        vals = []
        cnts = []
        for x in a:
            if vals and vals[-1] == x:
                cnts[-1] += 1
            else:
                vals.append(x)
                cnts.append(1)

        m = len(vals)

        # A beneficial swap is possible around:
        # X ... Y X ... Y
        # where the two middle runs are single elements.
        # Each such operation reduces the required operation count by 1.
        intervals = []
        for i in range(m - 2):
            if vals[i] == vals[i + 2] and cnts[i + 1] == 1 and cnts[i + 2] == 1:
                ok = False
                if i > 0 and vals[i - 1] == vals[i + 1]:
                    ok = True
                if i + 3 < m and vals[i + 3] == vals[i + 1]:
                    ok = True
                if ok:
                    intervals.append((i, i + 2))

        # Maximum number of non-overlapping beneficial transformations.
        intervals.sort(key=lambda x: x[1])
        gain = 0
        last_end = -1
        for l, r in intervals:
            if l > last_end:
                gain += 1
                last_end = r

        out.append(str(m - gain))

    print("\n".join(out))

