import sys
from array import array

def main():
    s = sys.stdin.buffer.readline().strip()
    n = len(s)

    rev = s[::-1]

    pi = array('I', [0]) * n
    j = 0
    for i in range(1, n):
        while j > 0 and rev[i] != rev[j]:
            j = pi[j - 1]
        if rev[i] == rev[j]:
            j += 1
        pi[i] = j

    j = 0
    for c in s:
        while j > 0 and c != rev[j]:
            j = pi[j - 1]
        if c == rev[j]:
            j += 1

    answer = s + s[:n - j][::-1]
    sys.stdout.buffer.write(answer + b'\n')

if __name__ == "__main__":
    main()

