import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())

    graph = [[] for _ in range(N)]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        graph[u].append(v)
        graph[v].append(u)

    color = [-1] * N
    has_odd_component = False
    side_sum_parity = 0

    for start in range(N):
        if color[start] != -1:
            continue

        q = deque([start])
        color[start] = 0
        cnt = [1, 0]

        while q:
            v = q.popleft()
            for to in graph[v]:
                if color[to] == -1:
                    color[to] = color[v] ^ 1
                    cnt[color[to]] += 1
                    q.append(to)

        if (cnt[0] + cnt[1]) % 2 == 1:
            has_odd_component = True
        side_sum_parity ^= (cnt[0] & 1)

    if N % 2 == 1:
        first_wins = (M % 2 == 1)
    elif has_odd_component:
        first_wins = (M % 2 == 0)
    else:
        first_wins = (side_sum_parity != (M & 1))

    print("Aoki" if first_wins else "Takahashi")

if __name__ == "__main__":
    main()

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def is_smooth(x: int) -> bool:
            for p in (2, 3, 5, 7):
                while x % p == 0:
                    x //= p
            return x == 1

        def count_without_zero(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            length = len(digits)

            total = sum(9 ** k for k in range(1, length))

            for i, digit in enumerate(digits):
                remaining = length - i - 1

                if digit == 0:
                    break

                total += (digit - 1) * (9 ** remaining)

                if i == length - 1:
                    total += 1

            return total

        def count_nonzero_beautiful(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            m = len(digits)
            answer = 0

            for target_sum in range(1, 9 * m + 1):
                if not is_smooth(target_sum):
                    continue

                initial_rem = 1 % target_sum

                # States are (digit_sum, product_mod_target_sum) -> count.
                # "free" means already smaller than n's prefix.
                # Sum 0 uniquely represents the not-started-yet state.
                free = {}
                tight = {(0, initial_rem): 1}

                for pos, limit in enumerate(digits):
                    remaining = m - pos - 1
                    next_free = {}
                    next_tight = {}

                    for (cur_sum, rem), count in free.items():
                        start_digit = 0 if cur_sum == 0 else 1

                        for digit in range(start_digit, 10):
                            new_sum = cur_sum + digit

                            if new_sum > target_sum:
                                continue
                            if new_sum + 9 * remaining < target_sum:
                                continue
                            if new_sum > 0 and new_sum + remaining > target_sum:
                                continue

                            if cur_sum == 0 and digit == 0:
                                new_rem = rem
                            else:
                                new_rem = (rem * digit) % target_sum

                            key = (new_sum, new_rem)
                            next_free[key] = next_free.get(key, 0) + count

                    for (cur_sum, rem), count in tight.items():
                        start_digit = 0 if cur_sum == 0 else 1

                        for digit in range(start_digit, limit + 1):
                            new_sum = cur_sum + digit

                            if new_sum > target_sum:
                                continue
                            if new_sum + 9 * remaining < target_sum:
                                continue
                            if new_sum > 0 and new_sum + remaining > target_sum:
                                continue

                            if cur_sum == 0 and digit == 0:
                                new_rem = rem
                            else:
                                new_rem = (rem * digit) % target_sum

                            key = (new_sum, new_rem)

                            if digit == limit:
                                next_tight[key] = next_tight.get(key, 0) + count
                            else:
                                next_free[key] = next_free.get(key, 0) + count

                    free = next_free
                    tight = next_tight

                answer += free.get((target_sum, 0), 0)
                answer += tight.get((target_sum, 0), 0)

            return answer

        def count_beautiful_up_to(n: int) -> int:
            if n <= 0:
                return 0

            no_zero = count_without_zero(n)
            contains_zero = n - no_zero

            return contains_zero + count_nonzero_beautiful(n)

        return count_beautiful_up_to(r) - count_beautiful_up_to(l - 1)

from typing import List


class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)

        if n - 1 < k:
            return [0] * n

        children = [{}]
        count = [0]
        depth = [0]
        max_len = 0

        # Build trie and count how many words pass through each node.
        for word in words:
            node = 0
            max_len = max(max_len, len(word))
            for ch in word:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)
                node = nxt
                count[node] += 1

        # qualified[d] = number of trie nodes at depth d shared by at least k words.
        qualified = [0] * (max_len + 1)
        for node in range(1, len(children)):
            if count[node] >= k:
                qualified[depth[node]] += 1

        # Segment tree storing the maximum currently valid prefix length.
        size = 1
        while size <= max_len:
            size <<= 1

        seg = [0] * (2 * size)
        for d in range(1, max_len + 1):
            if qualified[d] > 0:
                seg[size + d] = d

        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[i * 2], seg[i * 2 + 1])

        def update(pos: int, value: int) -> None:
            idx = size + pos
            seg[idx] = value
            idx //= 2
            while idx:
                new_value = max(seg[idx * 2], seg[idx * 2 + 1])
                if seg[idx] == new_value:
                    break
                seg[idx] = new_value
                idx //= 2

        answer = [0] * n

        for i, word in enumerate(words):
            node = 0
            removed_depths = []

            # A depth disappears only if its unique qualifying node
            # has exactly k words passing through it.
            for d, ch in enumerate(word, 1):
                node = children[node][ch]
                if count[node] == k and qualified[d] == 1:
                    removed_depths.append(d)

            for d in removed_depths:
                update(d, 0)

            answer[i] = seg[1]

            for d in removed_depths:
                update(d, d)

        return answer

