import math

def main():
    N = int(sys.stdin.readline())

    for d in range(1, 1_000_001):
        if d * d * d >= N:
            break
        if N % d != 0:
            continue

        q = N // d
        disc = 12 * q - 3 * d * d
        if disc < 0:
            continue

        r = math.isqrt(disc)
        if r * r != disc:
            continue

        if r <= 3 * d or (r - 3 * d) % 6 != 0:
            continue

        y = (r - 3 * d) // 6
        x = y + d

        if y > 0 and x * x * x - y * y * y == N:
            print(x, y)
            return

    print(-1)

