import sys
from collections import deque

sys.setrecursionlimit(1000000)

class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, len(self.g[to]), cap])
        self.g[to].append([fr, len(self.g[fr]) - 1, 0])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        q = deque([s])
        self.level[s] = 0
        while q:
            v = q.popleft()
            for to, rev, cap in self.g[v]:
                if cap > 0 and self.level[to] < 0:
                    self.level[to] = self.level[v] + 1
                    q.append(to)
        return self.level[t] >= 0

    def dfs(self, v, t, f):
        if v == t:
            return f
        while self.it[v] < len(self.g[v]):
            i = self.it[v]
            e = self.g[v][i]
            to, rev, cap = e
            if cap > 0 and self.level[v] < self.level[to]:
                d = self.dfs(to, t, min(f, cap))
                if d:
                    e[2] -= d
                    self.g[to][rev][2] += d
                    return d
            self.it[v] += 1
        return 0

    def max_flow(self, s, t, limit):
        flow = 0
        while flow < limit and self.bfs(s, t):
            self.it = [0] * self.n
            while flow < limit:
                f = self.dfs(s, t, limit - flow)
                if f == 0:
                    break
                flow += f
        return flow


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, k = data[0], data[1], data[2]
    edges = []
    p = 3
    for _ in range(m):
        u = data[p] - 1
        v = data[p + 1] - 1
        p += 2
        edges.append((u, v))

    def feasible(L):
        if L == 0:
            return True

        def node(v, level):
            return v * L + (level - 1)

        source = n * L
        sink = source + 1
        dinic = Dinic(sink + 1)
        INF = k + 1

        # Fix vertex 1 to height 0.
        for level in range(1, L + 1):
            dinic.add_edge(node(0, level), sink, INF)

        # Fix vertex N to height L.
        for level in range(1, L + 1):
            dinic.add_edge(source, node(n - 1, level), INF)

        # Enforce: height(v) >= i+1 => height(v) >= i.
        for v in range(n):
            for level in range(2, L + 1):
                dinic.add_edge(node(v, level), node(v, level - 1), INF)

        for u, v in edges:
            for level in range(1, L + 1):
                # Cost 1 when height(v) > height(u).
                dinic.add_edge(node(v, level), node(u, level), 1)

            # Enforce height(v) <= height(u) + 1.
            for level in range(2, L + 1):
                dinic.add_edge(node(v, level), node(u, level - 1), INF)

        return dinic.max_flow(source, sink, k + 1) <= k

    low, high = 0, k + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
