def normalize(s, x, y):
    runs = []
    prev = None
    cnt = 0
    for ch in s:
        b = 1 if ch == '1' else 0
        if b == prev:
            cnt += 1
        else:
            if prev is not None:
                runs.append((prev, cnt))
            prev = b
            cnt = 1
    if prev is not None:
        runs.append((prev, cnt))

    pending = runs[::-1]
    st = []

    while pending:
        bit, length = pending.pop()
        if length == 0:
            continue

        if st and st[-1][0] == bit:
            st[-1] = (bit, st[-1][1] + length)
        else:
            st.append((bit, length))

        if len(st) >= 2:
            a_bit, a_len = st[-2]
            b_bit, b_len = st[-1]

            if a_bit == 0 and b_bit == 1 and a_len >= x and b_len >= y:
                st.pop()
                st.pop()

                q, r = divmod(a_len, x)
                p, s = divmod(b_len, y)

                replacement = [
                    (0, r),
                    (1, p * y),
                    (0, q * x),
                    (1, s),
                ]

                for item in reversed(replacement):
                    if item[1] > 0:
                        pending.append(item)

    return st


