class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        pairs_at_right = [[] for _ in range(n + 1)]

        for idx, (a, b) in enumerate(conflictingPairs):
            left, right = sorted((a, b))
            pairs_at_right[right].append((left, idx))

        gains = [0] * len(conflictingPairs)

        largest_left = 0
        second_largest_left = 0
        largest_pair_id = -1

        total_valid = 0

        for right in range(1, n + 1):
            for left, pair_id in pairs_at_right[right]:
                if left > largest_left:
                    second_largest_left = largest_left
                    largest_left = left
                    largest_pair_id = pair_id
                else:
                    second_largest_left = max(second_largest_left, left)

            total_valid += right - largest_left

            if largest_pair_id != -1:
                gains[largest_pair_id] += largest_left - second_largest_left

        return total_valid + max(gains)

