class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        length = n + m - 1

        word = ['a'] * length
        fixed = [False] * length

        # Apply all mandatory 'T' constraints.
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if fixed[pos] and word[pos] != str2[j]:
                        return ""
                    word[pos] = str2[j]
                    fixed[pos] = True

        # Handle 'F' constraints greedily.
        for i in range(n):
            if str1[i] != 'F':
                continue

            matches = True
            for j in range(m):
                if word[i + j] != str2[j]:
                    matches = False
                    break

            if not matches:
                continue

            # Break this occurrence as far right as possible,
            # preserving lexicographic minimality.
            changed = False
            for j in range(m - 1, -1, -1):
                pos = i + j
                if not fixed[pos] and word[pos] == 'a':
                    word[pos] = 'b'
                    changed = True
                    break

            if not changed:
                return ""

        # Final validation of all forbidden occurrences.
        for i in range(n):
            if str1[i] == 'F':
                matches = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        matches = False
                        break
                if matches:
                    return ""

        return ''.join(word)

