class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        LIMIT = 10**15

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(LIMIT, fact[i - 1] * i)

        def count_completions(odd_left: int, even_left: int, next_is_odd: bool) -> int:
            remaining = odd_left + even_left
            if remaining == 0:
                return 1

            if next_is_odd:
                needed_odd = (remaining + 1) // 2
                needed_even = remaining // 2
            else:
                needed_even = (remaining + 1) // 2
                needed_odd = remaining // 2

            if odd_left != needed_odd or even_left != needed_even:
                return 0

            return min(LIMIT, fact[odd_left] * fact[even_left])

        unused = list(range(1, n + 1))
        odd_left = (n + 1) // 2
        even_left = n // 2
        answer = []
        previous_parity = None

        for _ in range(n):
            chosen = False

            for i, value in enumerate(unused):
                parity = value & 1

                if previous_parity is not None and parity == previous_parity:
                    continue

                next_odd_left = odd_left - (1 if parity else 0)
                next_even_left = even_left - (1 if parity == 0 else 0)

                ways = count_completions(
                    next_odd_left,
                    next_even_left,
                    next_is_odd=(parity == 0)
                )

                if k > ways:
                    k -= ways
                else:
                    answer.append(value)
                    unused.pop(i)
                    odd_left = next_odd_left
                    even_left = next_even_left
                    previous_parity = parity
                    chosen = True
                    break

            if not chosen:
                return []

        return answer

