class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side
        positions = []

        for x, y in points:
            if y == 0:
                positions.append(x)
            elif x == side:
                positions.append(side + y)
            elif y == side:
                positions.append(3 * side - x)
            else:
                positions.append(4 * side - y)

        positions.sort()
        n = len(positions)
        doubled = positions + [p + perimeter for p in positions]

        def can(distance: int) -> bool:
            if distance == 0:
                return True

            m = 2 * n
            nxt = [m] * m
            j = 0

            for i in range(m):
                if j < i + 1:
                    j = i + 1
                target = doubled[i] + distance
                while j < m and doubled[j] < target:
                    j += 1
                nxt[i] = j

            for start in range(n):
                cur = start
                for _ in range(k - 1):
                    cur = nxt[cur]
                    if cur >= m:
                        break

                if cur < m and doubled[cur] <= doubled[start] + perimeter - distance:
                    return True

            return False

        low, high = 0, side + 1

        while low + 1 < high:
            mid = (low + high) // 2
            if can(mid):
                low = mid
            else:
                high = mid

        return low

