                    b = a
                    a = x
                elif x > b:
                    c = b
                    b = x
                elif x > c:
                    c = x

        if c > 0:
            down[v] = 1 + a + b + c
        else:
            down[v] = 1

    # up[v] = best size on parent's side when edge (parent[v], v) is selected.
    up = [0] * n
    ans = -1

    for v in order:
