class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')

        def occurrences(text: str, pattern: str):
            n = len(text)
            m = len(pattern)

            if m == 0:
                return list(range(n + 1))

            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and pattern[i] != pattern[j]:
                    j = pi[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(text):
                while j > 0 and ch != pattern[j]:
                    j = pi[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]

            return result

        occ_a = occurrences(s, a)
        occ_b = occurrences(s, b)
        occ_c = occurrences(s, c)

        la = len(a)
        lb = len(b)
        lc = len(c)

        ia = 0
        ib = 0
        best_a_start = -1
        best_start_for_c = -1
        answer = float('inf')

        for c_start in occ_c:
            while ib < len(occ_b) and occ_b[ib] + lb <= c_start:
                b_start = occ_b[ib]

                while ia < len(occ_a) and occ_a[ia] + la <= b_start:
                    best_a_start = max(best_a_start, occ_a[ia])
                    ia += 1

                if best_a_start != -1:
                    best_start_for_c = max(best_start_for_c, best_a_start)

                ib += 1

            if best_start_for_c != -1:
                answer = min(answer, c_start + lc - best_start_for_c)

        return -1 if answer == float('inf') else answer

