    N = data[0]
    A = data[1:]

    factors = {}

    for i, a in enumerate(A):
        x = a
        p = 2
        while p * p <= x:
            if x % p == 0:
                cnt = 0
                while x % p == 0:
                    x //= p
                    cnt += 1
                if p not in factors:
                    factors[p] = [0] * (N - 1)
                factors[p][i] = cnt
            p += 1 if p == 2 else 2
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (N - 1)
            factors[x][i] = 1

    ans = 1

    for prime, ds in factors.items():
        D = sum(ds)

        pw = [1] * (D + 1)
        for i in range(1, D + 1):
            pw[i] = pw[i - 1] * prime % MOD

        hit = [0] * (D + 1)
        nohit = [0] * (D + 1)

        hit[0] = 1
        for x in range(1, D + 1):
            nohit[x] = pw[x]

        for d in ds:
            if d == 0:
                for x in range(D + 1):
                    hit[x] = hit[x] * pw[x] % MOD
                    nohit[x] = nohit[x] * pw[x] % MOD
                continue

            new_hit = [0] * (D + 1)
            new_nohit = [0] * (D + 1)

            new_hit[0] = (hit[d] + nohit[d]) % MOD

            for y in range(1, D + 1):
                hv = 0
                nv = 0

                if y >= d:
                    hv += hit[y - d]
                    nv += nohit[y - d]

                if y + d <= D:
                    hv += hit[y + d]
                    nv += nohit[y + d]

                new_hit[y] = (hv % MOD) * pw[y] % MOD
                new_nohit[y] = (nv % MOD) * pw[y] % MOD

            hit = new_hit
            nohit = new_nohit

        total_for_prime = sum(hit) % MOD
        ans = ans * total_for_prime % MOD

    print(ans)

