class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        target = list(dict.fromkeys(target))
        m = len(target)
        full = (1 << m) - 1

        lcms = [1] * (1 << m)
        groups = {}

        for mask in range(1, 1 << m):
            bit = mask & -mask
            idx = bit.bit_length() - 1
            prev = mask ^ bit
            l = lcms[prev]
            l = l // gcd(l, target[idx]) * target[idx]
            lcms[mask] = l
            groups[l] = groups.get(l, 0) | mask

        choices = [(l, mask) for l, mask in groups.items()]

        transitions = [[] for _ in range(1 << m)]
        for state in range(1 << m):
            for _, cover in choices:
                new_state = state | cover
                if new_state != state:
                    transitions[state].append((new_state, cover))

        INF = 10 ** 100
        dp = [INF] * (1 << m)
        dp[0] = 0

        costs = [0] * len(choices)

        for x in nums:
            for i, (l, _) in enumerate(choices):
                rem = x % l
                costs[i] = 0 if rem == 0 else l - rem

            for state in range(full - 1, -1, -1):
                current = dp[state]
                if current == INF:
                    continue

                for i, (_, cover) in enumerate(choices):
                    new_state = state | cover
                    if new_state == state:
                        continue
                    candidate = current + costs[i]
                    if candidate < dp[new_state]:
                        dp[new_state] = candidate

        return dp[full]

