        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    # buckets[parity][used_nonroot_vertices]
    # parity: 1 = current last layer is odd, 0 = even
    buckets = [[{} for _ in range(N)] for _ in range(2)]

    # First layer: odd layer of size b, previous layer size is 1.
    for b in range(1, H + 1):
        base = b * (b - 1) // 2
        poly = [0] * (base + b + 1)
        scale = invfact[b]
        for k in range(b + 1):
            val = comb[b][k] * scale % MOD
            if (b - k) & 1:
                val = -val
            poly[base + k] = val
        buckets[1][b][(b, 0, b)] = poly

    final_poly = [0] * (EMAX + 1)

    def normalize(poly):
        res = [x % MOD for x in poly]
        while len(res) > 1 and res[-1] == 0:
            res.pop()
        return res

    def add_transition(target_dict, key, src, prev_size, new_size):
        """
        Multiply src by:
            x^(C(new_size,2)) * (x^prev_size - 1)^new_size / new_size!
        and add it into target_dict[key].
        """
        base = new_size * (new_size - 1) // 2
        max_shift = base + prev_size * new_size
        need_len = len(src) + max_shift

        tgt = target_dict.get(key)
        if tgt is None:
            tgt = [0] * need_len
            target_dict[key] = tgt
        elif len(tgt) < need_len:
            tgt.extend([0] * (need_len - len(tgt)))

        invf = invfact[new_size]
        src_len = len(src)

        for k in range(new_size + 1):
            coef = comb[new_size][k] * invf % MOD
            if (new_size - k) & 1:
                coef = -coef
            shift = base + prev_size * k

            for i in range(src_len):
                v = src[i]
                if v:
                    tgt[i + shift] += v * coef

    for total_used in range(1, N):
        # Current odd layer -> append an even layer
        current = buckets[1][total_used]
        if current:
            for (odd_used, even_used, last_size), raw_poly in list(current.items()):
                poly = normalize(raw_poly)

                if odd_used == H and even_used == H - 1:
                    for i, v in enumerate(poly):
                        final_poly[i] += v
                    continue

                remaining_even = (H - 1) - even_used
                if remaining_even <= 0:
                    continue

                for b in range(1, remaining_even + 1):
                    ntotal = total_used + b
                    key = (odd_used, even_used + b, b)
                    add_transition(buckets[0][ntotal], key, poly, last_size, b)

        # Current even layer -> append an odd layer
        current = buckets[0][total_used]
        if current:
            for (odd_used, even_used, last_size), raw_poly in list(current.items()):
                poly = normalize(raw_poly)

                if odd_used == H and even_used == H - 1:
                    for i, v in enumerate(poly):
                        final_poly[i] += v
                    continue

                remaining_odd = H - odd_used
                if remaining_odd <= 0:
                    continue

                for b in range(1, remaining_odd + 1):
                    ntotal = total_used + b
                    key = (odd_used + b, even_used, b)
                    add_transition(buckets[1][ntotal], key, poly, last_size, b)

    final_poly = [x % MOD for x in final_poly]

    # Convert polynomial in x = 1 + q into polynomial in q.
    # If G(x) = sum_d g_d x^d, then:
    # G(1+q) = sum_m (sum_{d>=m} g_d C(d,m)) q^m
    answers = [0] * (EMAX + 1)
    for m in range(EMAX + 1):
        s = 0
        for d in range(m, EMAX + 1):
            if final_poly[d]:
                s += final_poly[d] * comb[d][m]
        answers[m] = s % MOD

    multiplier = fact[N - 1]
    out = []
    for m in range(N - 1, EMAX + 1):
        out.append(str(answers[m] * multiplier % MOD))

    print(" ".join(out))

if __name__ == "__main__":
    main()

