    p_list = [p for p in data[2:] if p <= m]

    if not p_list:
        print(0)
        return

    p_list.sort()
    groups = []
    prev = p_list[0]
    cnt = 1
    for p in p_list[1:]:
        if p == prev:
            cnt += 1
        else:
            groups.append((prev, cnt))
            prev = p
            cnt = 1
    groups.append((prev, cnt))

    def feasible(x):
        total = 0
        for p, c in groups:
            k = (x // p + 1) // 2
            total += c * p * k * k
            if total > m:
                return False
        return True

    lo = 0
    hi = 2 * m + p_list[-1] + 1

    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid

    answer = 0
    for p, c in groups:
        answer += c * ((lo // p + 1) // 2)

    print(answer)

