import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, p = data[0], data[1]
    A = []
    pos = 2
    for _ in range(n):
        A.append(data[pos:pos + n])
        pos += n

    def matmul(X, Y, mod):
        Yt = list(zip(*Y))
        Z = []
        for row in X:
            if not any(row):
                Z.append([0] * n)
                continue
            out = []
            for col in Yt:
                s = 0
                for a, b in zip(row, col):
                    s += a * b
                out.append(s % mod)
            Z.append(out)
        return Z

    if p == 2:
        B = [[1 if A[i][j] == 0 else A[i][j] for j in range(n)] for i in range(n)]
        ans = matmul(B, B, 2)
        print("\n".join(" ".join(map(str, row)) for row in ans))
        return

    zero_count = 0
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if A[i][j] == 0:
                zero_count += 1
            else:
                C[i][j] = A[i][j] % p

    def matpow(M, e, mod):
        result = None
        base = M
        while e > 0:
            if e & 1:
                if result is None:
                    result = base
                else:
                    result = matmul(result, base, mod)
            e >>= 1
            if e:
                base = matmul(base, base, mod)
        return result

    ans = matpow(C, p, p)

    for a in range(n):
        if A[a][a] == 0:
            for r in range(n):
                ans[r][a] = (ans[r][a] + C[r][a]) % p
            for s in range(n):
                ans[a][s] = (ans[a][s] + C[a][s]) % p

    if p == 3:
        for u in range(n):
            for v in range(n):
                if u != v and A[u][v] == 0:
                    ans[u][v] = (ans[u][v] + C[v][u]) % p

    if zero_count & 1:
        for i in range(n):
            for j in range(n):
                ans[i][j] = (-ans[i][j]) % p

    print("\n".join(" ".join(map(str, row)) for row in ans))

if __name__ == "__main__":
    main()

import sys
from array import array

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, M = data[0], data[1]
    to = [x - 1 for x in data[2:2 + N]]

    indeg = [0] * N
    for v in range(N):
        indeg[to[v]] += 1

    queue = [v for v in range(N) if indeg[v] == 0]
    order = []
    head = 0

    while head < len(queue):
        v = queue[head]
        head += 1
        order.append(v)
        p = to[v]
        indeg[p] -= 1
        if indeg[p] == 0:
            queue.append(p)

    # prod[v][k-1] = product of prefix sums of all non-cycle child subtrees,
    # for value k assigned to v. None means all ones.
    prod = [None] * N

    for v in order:
        p = to[v]

        if prod[p] is None:
            prod[p] = array('I', [1]) * M
        parent_prod = prod[p]

        child_prod = prod[v]
        if child_prod is None:
            for i in range(M):
                parent_prod[i] = (parent_prod[i] * (i + 1)) % MOD
        else:
            s = 0
            for i in range(M):
                s += child_prod[i]
                if s >= MOD:
                    s -= MOD
                parent_prod[i] = (parent_prod[i] * s) % MOD

        prod[v] = None

    seen = [False] * N
    answer = 1

    for start in range(N):
        if indeg[start] == 0 or seen[start]:
            continue

        cycle = []
        v = start
        while not seen[v]:
            seen[v] = True
            cycle.append(v)
            v = to[v]

        acc = None
        for v in cycle:
            if prod[v] is None:
                continue
            if acc is None:
                acc = prod[v]
            else:
                pv = prod[v]
                for i in range(M):
                    acc[i] = (acc[i] * pv[i]) % MOD

        if acc is None:
            ways = M
        else:
            ways = sum(acc) % MOD

        answer = (answer * ways) % MOD

    print(answer)

if __name__ == "__main__":
    main()

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        fact = [1] * n
        inv_fact = [1] * n

        for i in range(1, n):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact[n - 1] = pow(fact[n - 1], MOD - 2, MOD)
        for i in range(n - 1, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        combinations = fact[n - 1] * inv_fact[k] % MOD * inv_fact[n - 1 - k] % MOD

        return combinations * m % MOD * pow(m - 1, n - 1 - k, MOD) % MOD

