class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def can(limit: int) -> bool:
            if limit == 1:
                flips_start_zero = 0
                flips_start_one = 0

                for i, ch in enumerate(s):
                    expected_zero = '0' if i % 2 == 0 else '1'
                    expected_one = '1' if i % 2 == 0 else '0'

                    if ch != expected_zero:
                        flips_start_zero += 1
                    if ch != expected_one:
                        flips_start_one += 1

                return min(flips_start_zero, flips_start_one) <= numOps

            operations = 0
            run_length = 1

            for i in range(1, n):
                if s[i] == s[i - 1]:
                    run_length += 1
                else:
                    operations += run_length // (limit + 1)
                    run_length = 1

            operations += run_length // (limit + 1)
            return operations <= numOps

        left, right = 1, n

        while left < right:
            mid = (left + right) // 2
            if can(mid):
                right = mid
            else:
                left = mid + 1

        return left

