import heapq

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)

    H = next(it)
    W = next(it)
    X = next(it)
    P = next(it) - 1
    Q = next(it) - 1

    grid = [next(it) for _ in range(H * W)]

    start = P * W + Q
    strength = grid[start]

    visited = bytearray(H * W)
    visited[start] = 1

    heap = []

    def add_neighbor(r, c):
        idx = r * W + c
        if not visited[idx]:
            visited[idx] = 1
            heapq.heappush(heap, (grid[idx], r, c))

    if P > 0:
        add_neighbor(P - 1, Q)
    if P + 1 < H:
        add_neighbor(P + 1, Q)
    if Q > 0:
        add_neighbor(P, Q - 1)
    if Q + 1 < W:
        add_neighbor(P, Q + 1)

    while heap:
        value, r, c = heap[0]

        if value * X >= strength:
            break

        heapq.heappop(heap)
        strength += value

        if r > 0:
            add_neighbor(r - 1, c)
        if r + 1 < H:
            add_neighbor(r + 1, c)
        if c > 0:
            add_neighbor(r, c - 1)
        if c + 1 < W:
            add_neighbor(r, c + 1)

    print(strength)

