    main()

import sys
from bisect import bisect_left

def main():
    input = sys.stdin.readline

    N, X = map(int, input().split())
    X -= 1
    A = list(map(int, input().split()))
    B = list(map(int, input().split()))
    P = [x - 1 for x in map(int, input().split())]
    Q = [x - 1 for x in map(int, input().split())]

    def get_cycle_and_positions(nxt):
        cycle = [X]
        pos = [-1] * N
        pos[X] = 0
        v = nxt[X]
        while v != X:
            pos[v] = len(cycle)
            cycle.append(v)
            v = nxt[v]
        return cycle, pos

    cycle_p, pos_p = get_cycle_and_positions(P)
    cycle_q, pos_q = get_cycle_and_positions(Q)

    min_p = None
    for i in range(N):
        if A[i]:
            if pos_p[i] == -1:
                print(-1)
                return
            if i != X:
                if min_p is None or pos_p[i] < min_p:
                    min_p = pos_p[i]

    min_q = None
    for i in range(N):
        if B[i]:
            if pos_q[i] == -1:
                print(-1)
                return
            if i != X:
                if min_q is None or pos_q[i] < min_q:
                    min_q = pos_q[i]

    red_sequence = [] if min_p is None else cycle_p[min_p:]
    blue_sequence = [] if min_q is None else cycle_q[min_q:]

    blue_pos = [-1] * N
    for i, v in enumerate(blue_sequence):
        blue_pos[v] = i

    lis = []
    for v in red_sequence:
        p = blue_pos[v]
        if p != -1:
            j = bisect_left(lis, p)
            if j == len(lis):
                lis.append(p)
            else:
                lis[j] = p

    lcs = len(lis)
    answer = len(red_sequence) + len(blue_sequence) - lcs
    print(answer)

